# TEST CASE 1: ROLE-BASED ACCESS CONTROL BOUNDARIES
# (Admin, Editor, Viewer)
# =============================================================================

def get_user(role: str, id: int = 99) -> 'User':
    """Helper to create a user instance for testing permissions."""
    return User(id=id, username=f"u{id}", email=f"{role}@test.com", role=role)

def test_role_access_control():
    """Tests read/write/delete access boundaries for admin, editor, and viewer roles."""

    # --- Setup Users ---
    admin = get_user("admin")
    editor = get_user("editor")
    viewer = get_user("viewer")

    actions = ["read", "write", "delete_own", "delete_any", "admin"]

    print("\n--- Testing User Roles Permissions ---")

    # 1. Admin Tests: Should pass all actions
    for action in actions:
        assert admin.has_permission(action) is True, f"Admin role failed to grant '{action}' permission."

    # 2. Editor Tests: Read, Write, Delete_own allowed
    for action in ["read", "write", "delete_own"]:
        assert editor.has_permission(action) is True, f"Editor role unexpectedly blocked '{action}'."
    # Check boundaries for Editor
    assert editor.has_permission("delete_any") is False, "Editor should not have delete_any permission."
    assert editor.has_permission("admin") is False, "Editor should not have admin permission."

    # 3. Viewer Tests: Read only
    assert viewer.has_permission("read") is True, "Viewer role incorrectly denied 'read' access."
    for action in ["write", "delete_own", "delete_any", "admin"]:
        assert viewer.has_permission(action) is False, f"Viewer role unexpectedly granted '{action}' permission."


