def test_create_user_validation_failures(manager: UserManager):
    """Tests user creation failure for invalid usernames and emails."""

    # --- Invalid Username Tests (Length/Format) ---
    with pytest.raises(UserValidationError, match="Username must be 3"):
        # Too short
        manager.create_user("a", "valid@email.com")

    with pytest.raises(UserValidationError, match="Username must be 3–50 characters long"):
        # Too long (exceeds standard test length)
        long_username = "A" * 51
        manager.create_user(long_username, "valid@email.com")

    with pytest.raises(UserValidationError, match="Username may only contain letters, digits, and underscores"):
        # Invalid characters (e.g., spaces)
        manager.create_user("bad user name", "valid@email.com")

    # --- Duplicate Username/Email Tests ---
    
    # 1. Successfully create a baseline user
    try:
        user1 = manager.create_user("testuser", "test@example.com", role="editor")
        assert user1 is not None
    except UserValidationError as e:
        pytest.skip(f"Could not setup base user due to {e}")


    # 2. Duplicate Username Failure
    with pytest.raises(UserValidationError, match="Username 'testuser' is already taken"):
        manager.create_user("TESTUSER", "another@email.com") # Case-insensitive check

    # 3. Duplicate Email Failure
    with pytest.raises(UserValidationError, match="Email 'test@example.com' is already registered"):
        manager.create_user("newuser", "test@example.com")


# =============================================================================
# TEST CASE 3: FULL CRUD LIFECYCLE PATH
# (Create -> Read -> Delete)
# =============================================================================

def test_full_crud_lifecycle(manager: UserManager):
    """Tests the full lifecycle path for a user: create, retrieve, delete."""
    
    test_username = "cruduser"
    test_email = f"{test_username}@lifecycle.com"

    # 1. CREATE (Check initial state and successful creation)
    try:
        # Attempt to create the user
        user = manager.create_user(test_username, test_email, role="admin")
        assert user is not None, "User should be successfully created."

    except UserValidationError as e:
        pytest.fail(f"Failed during user creation (CREATE step): {e}")
    except Exception as e:
         # Handle unexpected errors gracefully for test purposes
        pytest.fail(f"Unexpected error during user creation: {type(e).__name__}: {e}")

    # 2. READ (Verify the user can be retrieved)
    try:
        retrieved_user = manager.get_user(test_username)
        assert retrieved_user is not None, "User should exist after creation."
        assert retrieved_user.email == test_email, "Retrieved user email must match original email."

    # 3. DELETE (Ensure clean up happens regardless of previous failures)
    finally:
        try:
            manager.delete_user(test_username)
            print(f"\n--- Successfully deleted and cleaned up {test_username} ---")
        except UserNotFoundError:
             # If the deletion attempt fails because the user doesn't exist, that's fine for cleanup purposes
            pass
